#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1'000'000'007;

int64 modPow(int64 base, int64 exp) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int64> factorial(2 * n + 1);
    factorial[0] = 1;
    for (int i = 1; i <= 2 * n; ++i)
        factorial[i] = factorial[i - 1] * i % MOD;

    int64 answer = factorial[2 * n];
    answer = answer * modPow(factorial[n], MOD - 2) % MOD;
    answer = answer * modPow(factorial[n], MOD - 2) % MOD;
    answer = (answer - n + MOD) % MOD;

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1'000'000'007;

int64 modPow(int64 base, int64 exp) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int64 factorialExponent(int64 n, int64 p) {
    int64 exponent = 0;
    while (n > 0) {
        n /= p;
        exponent += n;
    }
    return exponent;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    int limit = static_cast<int>(2 * n);
    vector<bool> isPrime(limit + 1, true);
    vector<int> primes;

    if (limit >= 0) isPrime[0] = false;
    if (limit >= 1) isPrime[1] = false;

    for (int i = 2; i <= limit; ++i) {
        if (!isPrime[i]) continue;
        primes.push_back(i);
        if (1LL * i * i <= limit) {
            for (int64 j = 1LL * i * i; j <= limit; j += i)
                isPrime[static_cast<int>(j)] = false;
        }
    }

    int64 ans = 1;
    for (int p : primes) {
        int64 exponent = factorialExponent(2 * n - 1, p)
                       - factorialExponent(n, p)
                       - factorialExponent(n - 1, p);
        ans = ans * modPow(p, exponent) % MOD;
    }

    cout << (2 * ans % MOD - n % MOD + MOD) % MOD;
    return 0;
}

